#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto doop=[&](int x,int y){
        assert(x>0 && y>0 && x+y<n);
        vector<int> np(n);
        // C=p[n-y..n-1], B=p[x..n-y-1], A=p[0..x-1]
        int idx=0;
        for(int i=n-y;i<n;i++) np[idx++]=p[i];
        for(int i=x;i<n-y;i++) np[idx++]=p[i];
        for(int i=0;i<x;i++) np[idx++]=p[i];
        p=np;
        ops.push_back({x,y});
    };
    for(int k=0;k<n;k++){
        int pos=-1;
        for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
        if(pos==k) continue;
        if(n-k<3){
            // Only 2 elements left, just swap - but we need x+y<n with x,y>0
            // x=pos, y=n-pos -> x+y=n, invalid. Use: the remaining two must be swappable
            // Actually if n-k==2, pos=k+1, need to swap p[k] and p[k+1]
            // x=k+1, y=1: moves p[n-1] to front. If k+1+1<n ok
            if(k+1>0 && 1>0 && k+1+1<n) doop(k+1,1);
            // now find again
            for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
            if(pos==k) continue;
        }
        // Move val to position n-1
        if(pos!=n-1){
            int x=pos+1,y=1;
            if(x+y<n) doop(x,y);
            else{ // pos=n-2, so x=n-1,y=1,x+y=n. Use x=1,y=2 instead
                doop(1,2); // moves p[n-2] to pos 0
            }
            for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
            if(pos==k) continue;
            if(pos!=n-1){
                x=pos+1; y=1;
                if(x+y<n) doop(x,y);
                for(int i=k;i<n;i++) if(p[i]==k+1){pos=i;break;}
                if(pos==k) continue;
            }
        }
        // Now val is at n-1. Move to k: x=k, y=1 if k>0
        if(pos==n-1 && k>0 && k+1<n) doop(k,1);
        // if k==0: x can't be 0. Use x=1,y=1 won't help. x=n-1,y=... 
        else if(pos==n-1 && k==0) doop(1,1); // brings last to front? No: C=p[n-1],B=p[1..n-2],A=p[0] -> val at pos 0. 
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
